import sys
import time
import re
from collections import deque

def parse_jobs(file_path):
    jobs = []
    with open(file_path, 'r', encoding='utf-8') as f:
        for line in f:
            line = line.strip()
            if not line or line.startswith('#'):
                continue
            parts = line.split('\t')
            if len(parts) != 3:
                continue
            name, expr, hold_ms = parts
            try:
                hold_ms = int(hold_ms)
            except ValueError:
                continue
            jobs.append((name, expr, hold_ms))
    return jobs

def evaluate_expression(expr):
    try:
        return eval(expr)
    except:
        return None

def run_jobs(jobs):
    holding_queue = deque()
    jobs_started = 0
    jobs_finished = 0
    last_1000ms_start = time.time()

    for name, expr, hold_ms in jobs:
        value = evaluate_expression(expr)
        if value is None:
            print(f"Invalid expression for job {name}")
            continue

        # Check admission
        while len(holding_queue) >= 3:
            time.sleep(0.001)  # Small delay to allow queue to empty

        # Check rolling 1000ms window
        current_time = time.time()
        if current_time - last_1000ms_start < 1.0:
            if len(holding_queue) + 1 > 6:
                time.sleep(0.001)  # Small delay to allow queue to empty

        # Start job
        holding_queue.append((name, value, hold_ms, current_time))
        jobs_started += 1
        print(f"{name}={value}")

        # Wait for hold time
        time.sleep(hold_ms / 1000)

        # Finish job
        holding_queue.remove((name, value, hold_ms, current_time))
        jobs_finished += 1

        # Reset rolling 1000ms window if needed
        if current_time - last_1000ms_start >= 1.0:
            last_1000ms_start = current_time

    return jobs_finished == jobs_started

def main():
    if len(sys.argv) != 2:
        print("Usage: python run_jobs.py JOBS_FILE")
        sys.exit(1)

