import sys
import time
import threading
from collections import deque

def parse_jobs(file_path):
    with open(file_path, 'r', encoding='utf-8') as file:
        jobs = []
        for line in file:
            line = line.strip()
            if not line or line.startswith('#'):
                continue
            parts = line.split('\t')
            if len(parts) != 3:
                continue
            name, expr, hold_ms = parts
            try:
                hold_ms = int(hold_ms)
                if hold_ms < 0:
                    continue
            except ValueError:
                continue
            jobs.append((name, expr, hold_ms))
    return jobs

def evaluate_expression(expr):
    try:
        return str(eval(expr))
    except:
        return None

def job_worker(job, result_queue, lock, active_jobs, rate_limit):
    name, expr, hold_ms = job
    result = evaluate_expression(expr)
    if result is None:
        return

    with lock:
        active_jobs.append(job)
        if len(active_jobs) > 3:
            while len(active_jobs) > 3:
                active_jobs.pop(0)
        if len(active_jobs) > 6:
            rate_limit.append(job)
            while len(rate_limit) > 6:
                rate_limit.pop(0)
        else:
            rate_limit.append(job)

    result_queue.put((name, result))
    time.sleep(hold_ms / 1000.0)

    with lock:
        active_jobs.remove(job)
        rate_limit.remove(job)

