import sys
import time
import threading
from collections import deque

def evaluate_expression(expr):
    try:
        return str(eval(expr))
    except:
        return "0"

def process_jobs(job_file):
    jobs = []
    with open(job_file, 'r', encoding='utf-8') as f:
        for line in f:
            line = line.strip()
            if not line or line.startswith('#'):
                continue
            parts = line.split('\t')
            if len(parts) != 3:
                continue
            name, expr, hold_ms = parts
            jobs.append((name, expr, int(hold_ms)))

    job_queue = deque()
    holding_jobs = []
    holding_lock = threading.Lock()
    rate_limit_window = deque(maxlen=1000)
    rate_limit_lock = threading.Lock()
    rate_limit_start = time.time()

    def process_job(name, expr, hold_ms):
        value = evaluate_expression(expr)
        with open(sys.stdout.fileno(), 'w') as out:
            print(f"{name}={value}", file=out)

        with holding_lock:
            holding_jobs.append((name, hold_ms))

        while len(holding_jobs) > 3:
            time.sleep(0.001)

        with rate_limit_lock:
            rate_limit_window.append(time.time())
            while len(rate_limit_window) > 1000:
                rate_limit_window.popleft()
            if len(rate_limit_window) >= 1000:
                current_time = time.time()
                if current_time - rate_limit_start >= 1:
                    rate_limit_start += 1
                    rate_limit_window.clear()
                    rate_limit_window.append(current_time)
                else:
                    if len(rate_limit_window) >= 6:
                        time.sleep(0.001)

        time.sleep(hold_ms / 1000)

        with holding_lock:
            holding_jobs.remove((name, hold_ms))

    for name, expr, hold_ms in jobs:
        job_queue.append((name, expr, hold_ms))

    while job_queue:
        while len(holding_jobs) < 3 and job_queue:
            name, expr, hold_ms = job_queue.popleft()
            process_job(name, expr, hold_ms)

        if job_queue:
            time.sleep(0.001)

    sys.exit(0)

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python run_jobs.py JOBS_FILE", file=sys.stderr)
        sys.exit(1)
    process_jobs(sys.argv[1])
